// Получаем текущее время
const now = new Date();

// Добавляем 1 час
const future = new Date(now.getTime() + 60 * 60 * 1000);

// Функция для форматирования в ISO с часовым поясом +03:00
function formatWithOffset(date) {
  const offsetMinutes = 180; // +03:00 = 180 минут
  const sign = offsetMinutes >= 0 ? '+' : '-';
  const absOffset = Math.abs(offsetMinutes);
  const offsetHours = String(Math.floor(absOffset / 60)).padStart(2, '0');
  const offsetMins = String(absOffset % 60).padStart(2, '0');

  // Сдвигаем UTC время на нужный offset, чтобы получить локальное время
  const local = new Date(date.getTime() + offsetMinutes * 60 * 1000);

  const year = local.getUTCFullYear();
  const month = String(local.getUTCMonth() + 1).padStart(2, '0');
  const day = String(local.getUTCDate()).padStart(2, '0');
  const hours = String(local.getUTCHours()).padStart(2, '0');
  const minutes = String(local.getUTCMinutes()).padStart(2, '0');
  const seconds = String(local.getUTCSeconds()).padStart(2, '0');

  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}${sign}${offsetHours}:${offsetMins}`;
}

const result = formatWithOffset(future);

return [{
  json: {
    datetime: result
  }
}];
